<?php require_once __DIR__.'/../includes/auth.php'; $editing=true; $id=filter_input(INPUT_GET,'id',FILTER_VALIDATE_INT); $row=null; if($editing){$st=$pdo->prepare('SELECT * FROM suppliers WHERE id=?');$st->execute([$id]);$row=$st->fetch();if(!$row){flash('error','Supplier not found.');redirect('index.php');}} $pageTitle=$editing?'Edit supplier':'Add supplier';$base='/shop-inventory-management';$name=$row['name']??'';$phone=$row['phone']??'';$email=$row['email']??'';$address=$row['address']??'';$error=''; if($_SERVER['REQUEST_METHOD']==='POST'){csrf_check();$name=trim($_POST['name']??'');$phone=trim($_POST['phone']??'');$email=trim($_POST['email']??'');$address=trim($_POST['address']??'');if($name==='')$error='Supplier name is required.';elseif($email!==''&&!filter_var($email,FILTER_VALIDATE_EMAIL))$error='Enter a valid email address.';else{try{if($editing){$st=$pdo->prepare('UPDATE suppliers SET name=?,phone=?,email=?,address=? WHERE id=?');$st->execute([$name,$phone?:null,$email?:null,$address?:null,$id]);}else{$st=$pdo->prepare('INSERT INTO suppliers(name,phone,email,address) VALUES(?,?,?,?)');$st->execute([$name,$phone?:null,$email?:null,$address?:null]);}flash('success',$editing?'Supplier updated.':'Supplier added.');redirect('index.php');}catch(PDOException $e){$error='Could not save supplier. Check the information and try again.';}}}require __DIR__.'/../includes/header.php';require __DIR__.'/../includes/sidebar.php';?>
<div class="page-heading"><div><h1><?=e($pageTitle)?></h1><p>Supplier contact information.</p></div><a class="btn" href="index.php">← Back</a></div><div class="panel form-panel"><?php if($error):?><div class="alert error"><?=e($error)?></div><?php endif;?><form method="post"><input type="hidden" name="csrf_token" value="<?=e(csrf_token())?>"><label>Supplier name *<input name="name" maxlength="150" required value="<?=e($name)?>"></label><div class="form-row"><label>Phone<input name="phone" maxlength="30" value="<?=e($phone)?>"></label><label>Email<input name="email" type="email" maxlength="190" value="<?=e($email)?>"></label></div><label>Address<textarea name="address" rows="3"><?=e($address)?></textarea></label><div class="form-actions"><button class="btn primary"><?=$editing?'Update supplier':'Save supplier'?></button><a class="btn" href="index.php">Cancel</a></div></form></div><?php require __DIR__.'/../includes/footer.php';?>
